def load(path):
    return json.loads(path.read_text(encoding="utf-8"))

def save(path,obj):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")

book=load(BOOK)
assert book["book"]["number"]==9 and book["book"]["archangel"]=="michael"
psalms={p["number"]:p for p in book["psalmAnalyses"]}
assert sorted(psalms)==list(range(48,77)),sorted(psalms)
if not BASE.exists():
    frozen={str(n):{t["themeId"]:t for t in p["themes"]} for n,p in psalms.items()}
    assert sum(map(len,frozen.values()))==82,"Unexpected historical relation count"
    save(BASE,{"book":9,"archangel":"michael","originalRelationCount":82,"psalms":frozen})
baseline=load(BASE)
assert baseline["originalRelationCount"]==82
for n,p in psalms.items():
    original=baseline["psalms"][str(n)]
    for tid,relation in original.items():
        assert next((x for x in p["themes"] if x["themeId"]==tid),None)==relation,("historical difference",n,tid)

source={}
verses=0
for n,p in psalms.items():
    corpus=load(CORPUS/f"psalm-{n:03d}.json")
    assert corpus["id"]==p["recordId"] and corpus["archangel"]=="michael"
    assert corpus["title"]==p["title"]
    valid={v["number"] for v in corpus["verses"]}
    assert valid==set(range(1,len(valid)+1))
    source[n]=valid;verses+=len(valid)
new=0
for n,tid,refs,label,teaching,directness,importance in EVIDENCE:
    assert set(refs)<=source[n],(n,tid,refs)
    assert len(set(refs))==len(refs)
    assert not any(t["themeId"]==tid for t in psalms[n]["themes"]),(n,tid,"duplicate")
    assert teaching and len(teaching)>32
    psalms[n]["themes"].append({"themeId":tid,"label":label,"importance":importance,"directness":directness,"verseNumbers":refs,"teaching":"La Bible essénienne enseigne que "+teaching})
    new+=1
book["method"].setdefault("themeCoverageAudits",[]).append({"scope":"book-09-psalms-048-076","reviewedOn":"2026-11-08","source":"data/corpus/books/book-09/psalm-048.json through psalm-076.json","approach":"conservative-editorial-verse-evidence","originalRelationCount":82,"addedRelationCount":new,"verifiedVerseCount":verses,"sourcePsalmsModified":False})
book["bookSynthesis"]["centralAxis"]="Synthèse d’indexation non exclusive : le livre 9 de Michaël relie l’éveil de la conscience, la vérité de la parole, la fidélité aux engagements, la juste place de l’homme entre la Mère et le Père, le discernement, la protection du sacré et le service collectif de la Nation Essénienne. Chaque lien sert de porte d’entrée vers les versets sans épuiser leur enseignement."
book["bookSynthesis"]["majorThemes"]=["conscience","verite","alliance","nation-essenienne","monde-divin","lumiere","purete","discernement","responsabilite","fidelite","engagement","mere-terre","sagesse","pensee","parole","protection","guerison","ame","soutien-mutuel","liberte"]
save(BOOK,book)
print(f"BOOK09 EDITORIAL: 29 psalms, {verses} verses, 82 historical preserved, {new} added, {82+new} total")
